public static void addToClassPath(Vector<URL> cpV, String dir) {
    File file = new File(dir);
    if (!file.exists()) return;
    File[] jars = file.listFiles((d, name) -> name.endsWith(".jar"));
    for (File j : jars) {
        URL url = j.toURI().toURL();
        cpV.add(url);
    }
}

private static void addToClassPath(Vector<URL> cpV, String dir) {
    try {
        File directory = new File(dir).getCanonicalFile();
        if (!directory.exists() || !directory.isDirectory()) {
            throw new IllegalArgumentException("Directory does not exist or is not a directory");
        }
        for (File file : directory.listFiles()) {
            if (file.isFile() && file.getName().endsWith(".jar")) {
                URL url = file.toURI().toURL();
                cpV.add(url);
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}

