    URLClassLoader classLoader = new URLClassLoader(cpV.toArray(new URL[0]));
    File dirFile = new File(dir);
    if(dirFile.exists() && dirFile.isDirectory()) {
        File[] jarFiles = dirFile.listFiles(File::isFile);
        if(jarFiles != null) {
            for(File jarFile : jarFiles) {
                if(jarFile.getName().endsWith(".jar")) {
