public static Class<?>[] resolve Arguments(Type genericType, Class<?> targetType) {
  if (!genericType instanceof ParameterizedType) {
    return null; // Not parameterized, cannot resolve arguments
  }

  Type[] actualTypeArguments = ((ParameterizedType) genericType).getActualTypeArguments();
  Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

  for (int i = 0; i < actualTypeArguments.length; i++) {
    Type argumentType = actualTypeArguments[i];
    if (argumentType instanceof Class<?>) {
      resolvedArguments[i] = (Class<?>) argumentType;
    } else if (argumentType instanceof TypeVariable<?>) {
      TypeVariable<?> typeVariable = (TypeVariable<?>) argumentType;
      if (typeVariable.getGenericDeclaration() == targetType) {
        resolvedArguments[i] = targetType;
      } else if (typeVariable.getGenericDeclaration().equals(targetType.getGenericSuperclass())) {
        resolvedArguments[i] = targetType.getSuperclass();
      } else {
        return null; // Cannot resolve the type variable
      }
    } else if (argumentType instanceof WildcardType) {
      WildcardType wildcardType = (WildcardType) argumentType;
      if (wildcardType.getUpperBounds().length > 0 && wildcardType.getUpperBounds()[0] instanceof Class<?>) {
        Class<?> bound = (Class<?>) wildcardType.getUpperBounds()[0];
        resolvedArguments[i] = bound;
      } else {
        return null; // Cannot resolve the type bound
      }
    } else {
      return null; // Unsupported type
    }
  }

  return resolvedArguments;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();

    List<Class<?>> resolvedArguments = new ArrayList<>();
    for (Type typeArgument : typeArguments) {
        if (typeArgument instanceof ClassName) {
            // Assuming ClassName is just a simple string representation of type
            String typeName = ((ClassName) typeArgument).getName();
            try {
                resolvedArguments.add(Class.forName(typeName));
            } catch (ClassNotFoundException e) {
                // Invalid type name, skip it
                resolvedArguments.clear();
                break;
            }
        } else {
            // If actual type argument is not a ClassName, return null
            return null;
        }
    }

    return resolvedArguments.toArray(new Class<?>[0]);
}

