public List<TimeRange> buildTimeRanges(long start, long end) {
    long durationLimit = FETCH_DATA_DURATION;
    List<TimeRange> result = new ArrayList<>();
    TimeRange currentRange = new TimeRange(start, end);

    while (currentRange != null && currentRange.getEndTime() - currentRange.getStartTime() > durationLimit) {
        result.add(currentRange);
        long endOfPrevious = currentRange.getEndTime();
        currentRange = new TimeRange(endOfPrevious - durationLimit, endOfPrevious);
    }
    result.add(currentRange);

    return result;
}

