public List<TimeRange> buildTimeRanges(long start, long end) {
    if (start >= end) {
        throw new IllegalArgumentException("Start time must be less than end time");
    }
    if (end - start >= FETCH_DATA_DURATION.toMillis()) {
        throw new IllegalArgumentException("Range must be smaller than max allowed duration");
    }
    List<TimeRange> timeRanges = Collections.emptyList();
    while (start < end) {
        long duration = Math.min(FETCH_DATA_DURATION.toMillis(), end - start);
        timeRanges.add(new TimeRange(start, start + duration));
        start += duration;
    }
    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    // Ensure the start and end times are small
    if (start >= FETCH_DATA_DURATION || end >= FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Start and end times must be smaller than FETCH_DATA_DURATION");
    }
    // Step 1: Calculate the number of time periods
    int periods = (int) Math.ceil((end - start) / FETCH_DATA_PERIOD);

    // Step 2: Create the time ranges
    List<TimeRange> timeRanges = new ArrayList<>();
    for (int i = 0; i < periods; i++) {
        long nextStart = start + i * FETCH_DATA_PERIOD;
        long nextEnd = Math.min(start + (i + 1) * FETCH_DATA_PERIOD, end);
        timeRanges.add(new TimeRange(nextStart, nextEnd));
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start < 0 || end < 0 || start > end) {
        throw new IllegalArgumentException("Start and end times must be non-negative and start must be less than end");
    }
    if (Double.compare(end, TimeUtils.FETCH_DATA_DURATION) <= 0) {
        throw new IllegalArgumentException("End time must be greater than FETCH_DATA_DURATION seconds");
    }
    long stepSize = TimeUtils.FETCH_DATA_DURATION / 10; // Assuming each time range step is 0.1 seconds
    List<TimeRange> timeRanges = new ArrayList<>();
    for (long time = start; time <= end; time += stepSize) {
        timeRanges.add(new TimeRange(time, Math.min(time + stepSize, end)));
    }
    return timeRanges;
}

