public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    long startOfYear = timeBucket - ((timeBucket % 1000000000) - 1); // Start of the year
    long endOfYear = startOfYear + 365 * dayStep; // End of the year
    long startOfMonth = timeBucket - ((timeBucket % 100000000) - 1); // Start of the month
    long endOfMonth = startOfMonth + 30 * dayStep; // End of the month
    long startOfWeek = timeBucket - ((timeBucket % 10000000) - 1); // Start of the week
    long endOfWeek = startOfWeek + 6 * dayStep; // End of the week

    // Check the range of time bucket and return the compressed value
    if (timeBucket < startOfYear) {
        return timeBucket;
    } else if (timeBucket < endOfYear) {
        long compressedYear = (timeBucket - startOfYear) / dayStep + 1;
        return compressedYear * 1000000000; // Start of the year in the compressed values
    } else if (timeBucket < startOfMonth) {
        return timeBucket - ((timeBucket % 10000000) - 1); // Start of the month in the compressed values
    } else if (timeBucket < endOfMonth) {
        long compressedMonth = (timeBucket - startOfMonth) / dayStep + 1;
        return compressedMonth * 1000000000 + (timeBucket % 10000000) / 1000000; // End of the month in the compressed values
    } else if (timeBucket < startOfWeek) {
        return timeBucket - ((timeBucket % 10000000) - 1); // Start of the week in the compressed values
    } else if (timeBucket < endOfWeek) {
        long compressedWeek = (timeBucket - startOfWeek) / dayStep + 1;
        return compressedWeek * 1000000000 + (timeBucket % 10000000) / 1000000 + (timeBucket % 1000000) / 10000 + (timeBucket % 10000) / 10 + (timeBucket % 10); // End of the week in the compressed values
    } else {
        return timeBucket;
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive.");
    }
    long week = timeBucket / 7;
    long day = week % dayStep;
    return timeBucket - (day * dayStep);
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Input values must be positive.");
    }

    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;

    long reFormattedDay = day;
    while (reFormattedDay % dayStep > 0) {
        reFormattedDay--;
    }

    return (year * 10000 + month * 100 + reFormattedDay);
}

