    // Divide the time bucket by the dayStep to get the new bucket
    long newBucket = timeBucket / dayStep;
    // Return the new bucket
    return newBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Check if the time bucket is less than zero
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Time bucket cannot be less than zero");
    }

    // Check if the dayStep is not a positive integer
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Day step must be a positive integer");
    }

    long year = timeBucket / (24 * 60 * 60 * 1000 * 365);
    long month = (timeBucket % (24 * 60 * 60 * 1000 * 365)) / (24 * 60 * 60 * 1000 * 30);
    long day = (timeBucket % (24 * 60 * 60 * 1000 * 30)) / (24 * 60 * 60 * 1000);
    long hour = (timeBucket % (24 * 60 * 60 * 1000)) / (24 * 60 * 60);
    long minute = (timeBucket % (24 * 60 * 60)) / (60 * 60);
    long second = (timeBucket % (24 * 60 * 60)) % 60;

    // Calculate the leading parts of the time bucket
    long leadingParts = year * (24 * 60 * 60 * 1000 * 365) + month * (24 * 60 * 60 * 1000 * 30) + day * (24 * 60 * 60 * 1000) + hour * (60 * 60);

    // Calculate the leading parts with dayStep offset
    long leadingPartsOffset = leadingParts + (dayStep - 1) * 24 * 60 * 60 * 1000;

    return leadingPartsOffset;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    int result = 0;
    for (int i = index; i < index + len; i++) {
        int b = str.charAt(i);
        if (b >= 0x80 && b < 0xC0) {
            throw new IllegalArgumentException("Invalid UTF-8 codepoint at index " + i);
        }
        if (b < 0x80) {
            result++;
            continue;
        }
        if (b >= 0xC2 && b < 0xE0) {
            result += 2;
        } else if (b >= 0xE0 && b < 0xF0) {
            result += 3;
        } else if (b >= 0xF0 && b < 0xF8) {
            result += 4;
        } else if (b >= 0xF8 && b < 0xFC) {
            result += 5;
        } else if (b >= 0xFC && b < 0xFE) {
            result += 6;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 codepoint at index " + i);
        }
        if (i + len < result) {
            throw new IllegalArgumentException("Invalid UTF-8 string at index " + i);
        }
    }
    return result;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
        if (str == null || index < 0 || len < 0 || index + len > str.length()) {
            throw new IllegalArgumentException("Invalid index or length");
        }

        int utf8Size = 0;
        int count = 0;
        for (int i = index; i < index + len; i++) {
            char currentChar = str.charAt(i);
            if (currentChar == '\uD800') {
                if (i + 1 < str.length() && str.charAt(i + 1) >= '\uDC00' && str.charAt(i + 1) <= '\uDBFF') {
                    utf8Size += 2;
                    i++;
                } else {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence at index " + i);
                }
            } else {
                utf8Size += codePointLength(currentChar);
            }
            count++;
            if (count == 32) {
                break;
            }
        }

        return utf8Size;
    }

private static int codePointLength(int codePoint) {
        if (Character.isSupplementaryCodePoint(codePoint)) {
            return 2;
        }
        return 1;
    }

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        int byteValue = str.charAt(i) & 0xFF;
        if (byteValue < 0x80) {
            size++; // Single byte (ASCII)
        } else if (byteValue < 0xE0) {
            size += 2; // 2-byte sequence (UTF-8)
        } else if (byteValue < 0xF0) {
            size += 3; // 3-byte sequence (UTF-8)
        } else {
            size += 4; // 4-byte sequence (UTF-8)
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int utf8Size = 0;
    for (int i = index; i < index + len; i++) {
        int ch = str.charAt(i);
        if (ch >= 0x80) {
            utf8Size += 0x3 + ((ch >> 5) & 3); // Calculate length of multi-byte character
        } else {
            utf8Size += 1; // Single-byte character
        }
    }
    return utf8Size;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    int result = 0;
    int i = index;
    while (i < index + len) {
        if (str.charAt(i) >= 0x80) {
            int mask = index + len - i + 1;
            int count = 0;
            while (mask % 7 == 0 && mask > 0) {
                mask /= 7;
                count++;
            }
            result += Math.max(1, count);
            i += Math.max(1, count);
        } else {
            result++;
            i++;
        }
    }
    return result;
}

