    public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
        if (str == null || str.length() == 0) {
            throw new IllegalArgumentException("Input string cannot be null or empty");
        }

        byte[] utf8Bytes = str.getBytes(StandardCharsets.UTF_8);

        int currentOffset = 0;
        int index = 0;
        int nextChar;

        while (index < utf8Bytes.length) {
            nextChar = utf8Bytes[index] & 0xFF;

            if (nextChar < 0x80) {
                lb.put((byte) nextChar);
                currentOffset += 1;
                index += 1;
            } else if (nextChar < 0xC0) {
                if (index == utf8Bytes.length - 1) {
                    throw new IllegalArgumentException("String contains invalid UTF-8 character");
                }
                int surrogate = utf8Bytes[index++] & 0xFF | (utf8Bytes[index++] & 0xFF) << 8;
                sb.append(Character.toCodePoint(0xD800, 0xDC00 | surrogate));
                currentOffset += 2;
            } else if (nextChar < 0xE0) {
                if (index >= utf8Bytes.length - 2) {
                    throw new IllegalArgumentException("String contains invalid UTF-8 character");
                }
                int secondByte = utf8Bytes[index++] & 0xFF | (utf8Bytes[index++] & 0xFF) << 8;
                sb.append(Character.toCodePoint(0xE000, 0xFFFF | ((secondByte >> 6) & 0x3F) << 10 | (secondByte & 0x3F) << 6));
                currentOffset += 3;
            } else if (nextChar < 0xF0) {
                if (index >= utf8Bytes.length - 3) {
                    throw new IllegalArgumentException("String contains invalid UTF-8 character");
                }
                int thirdByte = utf8Bytes[index++] & 0xFF | (utf8Bytes[index++] & 0xFF) << 8 | (utf8Bytes[index++] & 0xFF) << 16;
                sb.append(Character.toCodePoint(0x10000, 0x10FFFF | ((thirdByte >> 12) & 0xF) << 24 | ((thirdByte >> 6) & 0x3F) << 10 | (thirdByte & 0x3F) << 6));
                currentOffset += 4;
            } else if (nextChar < 0xF8) {
                if (index >= utf8Bytes.length - 4) {
                    throw new IllegalArgumentException("String contains invalid UTF-8 character");
                }
                int fourthByte = utf8Bytes[index++] & 0xFF | (utf8Bytes[index++] & 0xFF) << 8 | (utf8Bytes[index++] & 0xFF) << 16 | (utf8Bytes[index++] & 0xFF) << 24;
                sb.append(Character.toCodePoint(0x200000, 0x20FFFFF | ((fourthByte >> 18) & 0x7) << 32 | ((fourthByte >> 12) & 0xF) << 24 | ((fourthByte >> 6) & 0x3F) << 10 | (fourthByte & 0x3F) << 6));
                currentOffset += 5;
            } else if (nextChar < 0xFC) {
                if (index >= utf8Bytes.length - 5) {
                    throw new IllegalArgumentException("String contains invalid UTF-8 character");
                }
                int fifthByte = utf8Bytes[index++] & 0xFF | (utf8Bytes[index++] & 0xFF) << 8 | (utf8Bytes[index++] & 0xFF) << 16 | (utf8Bytes[index++] & 0xFF) << 24 | (utf8Bytes[index++] & 0xFF) << 32;
                sb.append(Character.toCodePoint(0x4000000, 0x40FFFFF | ((fifthByte >> 24) & 0x3) << 36 | ((fifthByte >> 18) & 0xF) << 32 | ((fifthByte >> 12) & 0xF) << 24 | ((fifthByte >> 6) & 0x3F) << 10 | (fifthByte & 0x3F) << 6));
                currentOffset += 6;
            } else {
                // Extended UTF-16 character (32-bit code units)
                int nextTwoBytes = (utf8Bytes[index++] & 0xFF) | (utf8Bytes[index++] & 0xFF) << 8;
                sb.appendCodePoint(nextTwoBytes);
                currentOffset += 2;
            }
        }

        lb.bufferData(currentOffset);
        lb.currentOffset(currentOffset);
        lb.limit(lb.offset + currentOffset);

        return lb;
    }
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }

    int length = str.length();
    lb.ensureRoom(length * 2); // At least 2 bytes for UTF-8 encoding
    int cursor = 0;

    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            // 1-byte ASCII character
            lb.write(c);
            cursor++;
        } else if (c < 0xC0) {
            if (c > 0x7F) {
                throw new IllegalArgumentException("Invalid UTF-8 character: " + c);
            }
            // 2-byte encoded UTF-8 character
            lb.write((byte) (0xC0 | (c >> 6)));
            lb.write((byte) (0x80 | (c & 0x3F)));
            cursor += 2;
        } else if (c < 0xE0) {
            if (c > 0xBF || i + 1 == length) {
                throw new IllegalArgumentException("Invalid UTF-8 character: " + c);
            }
            // 3-byte encoded UTF-8 character
            lb.write((byte) (0xE0 | (c >> 6)));
            lb.write((byte) (0x80 | ((c >> 2) & 0x3F)));
            lb.write((byte) (0x80 | (c & 0x3F)));
            cursor += 3;
        } else if (c < 0xF0) {
            if (c > 0xEF || i + 2 == length) {
                throw new IllegalArgumentException("Invalid UTF-8 character: " + c);
            }
            // 4-byte encoded UTF-8 character
            lb.write((byte) (0xF0 | (c >> 6)));
            lb.write((byte) (0x80 | ((c >> 4) & 0x3F)));
            lb.write((byte) (0x80 | ((c >> 2) & 0x3F)));
            lb.write((byte) (0x80 | (c & 0x3F)));
            cursor += 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 character: " + c);
        }
    }

    return lb;
}

