    ByteArrayOutputStream outs = new ByteArrayOutputStream();
    try {
        outs.write(str.getBytes());
        byte[] bytes = outs.toByteArray();
        ByteBuffer entireComponents = ByteBuffer.wrap(bytes);
        lb.writeByteSequence(entireComponents);
    } catch (IOException e){
