public class PathDecoder {

    /**
     * Decode the path component of a URI as path segments.
     *
     * @param u the URI. If the path component is an absolute path component then the leading '/' is ignored and is not considered a delimiator of a path segment.
     * @param decode true if the path segments of the path components should be in decoded form.
     * @return the list of decoded path segments.
     */
    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        Path path = Paths.get(u.getPath());
        List<PathSegmentImpl> decodedPathSegments = new ArrayList<>();

        if (decode) {
            try {
                String filePath = path.toUri().getPath();
                decodedPathSegments = Files.readAllLines(path).stream()
                                        .map(String::trim)
                                        .map(segment -> segment.replaceFirst("^/", ""))
                                        .filter(segment -> !segment.isEmpty())
                                        .map(PathSegmentImpl::new)
                                        .collect(Collectors.toList());
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        return decodedPathSegments;
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }

    if (u.isAbsolute()) {
        u = u.normalize();
    }

    return u.getPath().isEmpty() ? Collections.emptyList() : Arrays.stream(u.getPath().split("/"))
            .map(part -> decode ? decodePathSegment(part) : part)
            .collect(Collectors.toList());
}

private static List<PathSegmentImpl> decodePath(URI u, boolean decode) throws URISyntaxException {
  if (u.isAbsolute() && !decode) {
    throw new URISyntaxException(u.toString(), "Absolute path component since decode false");
  }

  List<PathSegmentImpl> pathSegments = new ArrayList<>();

  for (int i = 0; i < u.getRawPath().length(); i++) {
    StringBuilder segment = new StringBuilder();
    while (i < u.getRawPath().length() && u.getRawPath().charAt(i) != '/') {
      segment.append(u.getRawPath().charAt(i));
      i++;
    }

    List<PathSegmentImpl> chunks = pathSegments.isEmpty() ? List.of() : pathSegments.get(pathSegments.size() - 1).getChunks();

    for (PathSegmentImpl chunk : chunks) {
      String preName = chunk.getName();
      if (!"".equals(preName)) {
        PathSegmentImpl newChunk = new PathSegmentImpl(new Name(pathSegments.size() + 1), preName + segment.toString(), newVersion(), PathScope.PUBLIC);
        pathSegments.get(pathSegments.size() - 1).addChunk(newChunk);
      }
      chunk.append(segment.toString());
    }

    pathSegments.add(new Chunk(chunk.getName() + segment.toString()));
  }

  return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // If the path component is an absolute path component, ignore the leading '/' and don't consider it a delimiator.
    String pathSegment = u.getPath();
    if (u.isAbsolute() && pathSegment != null && pathSegment.startsWith("/")) {
        pathSegment = pathSegment.substring(1);
    }

    // If decode is true, decode the path segments.
    if (decode) {
        List<PathSegmentImpl> decodedSegments = new ArrayList<>();
        String[] segments = pathSegment.split("/");
        for (String segment : segments) {
            decodedSegments.add(new PathSegmentImpl(filePath/toPath(isolatedFileSystem, normalizedPath(segment))));
        }
        return decodedSegments;
    } else {
        return Arrays.asList(new PathSegmentImpl(pathSegment));
    }
}

