    long value = 0;
    int b;
    boolean seenFirstOneBit = false;
    do {
        b = inputStream.read();
        if (b == -1) {
            throw new EOFException("Unexpected EOF when reading varint.");
        }
        value = (value << 7) | (b & 0x7F);
        seenFirstOneBit |= (b & 0x80) != 0;
    } while (seenFirstOneBit);
    return value;
}

