public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    double originX = box.getX();
    double width = box.getWidth();
    double height = box.getHeight();

    // Calculate the new x coordinate for the new boxes
    double midpointX = originX + width / 2;

    // Calculate the new box heights
    double heightFirst = height / 2;
    double heightSecond = height / 2;

    // Create the new boxes
    Box2D boxFirst = new Box2D(originX, midpointX, width / 2, heightFirst);
    Box2D boxSecond = new Box2D(midpointX, originX + width, width / 2, heightSecond);

    // Return the result
    return new Pair<>(boxFirst, boxSecond);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box)
{
    // Calculate the middle point of the box on the x-axis
    double middle = box.getX() + (box.getWidth() / 2);

    // Create two new boxes: one for the left half and one for the right half
    Box2D leftBox = new Box2D(box.getX(), box.getY(), middle, box.getHeight());
    Box2D rightBox = new Box2D(middle, box.getY(), box.getWidth() - middle, box.getHeight());

    // Return the pair of resulting boxes
    return new Pair<>(leftBox, rightBox);
}

