public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the width of the box
    double width = box.getWidth();

    // Calculate the center of the box
    double centerX = box.getX() + width / 2;

    // Calculate the top-left corner of the first box
    double top-leftX = centerX - width / 2;
    double top-leftY = box.getY();

    // Calculate the width of the first box
    double firstBoxWidth = width / 2;

    // Generate the top-left corner and width for the first box
    Pair<Double, Double> topLeft1 = Pair.with(top-leftX, top-leftY);
    Pair<Double, Double> width1 = Pair.with(firstBoxWidth, 0);

    // Generate the top-left corner and width for the second box
    Pair<Double, Double> topLeft2 = Pair.with(centerX + width / 2, top-leftY);
    Pair<Double, Double> width2 = Pair.with(firstBoxWidth, 0);

    // Return the two resulting boxes as a pair
    return new Pair<>(topLeft1, width1, topLeft2, width2);
}

