public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    int maxLength = linkedBuffer.maxLength; // Assuming this method is available
    int written = 0;

    while (written < maxLength) {
        byte[] chunk = node.getChunk(written);
        int bytesWritten = out.write(chunk, 0, Math.min(chunk.length, maxLength - written));
        if (bytesWritten == 0) {
            break;
        }
        totalSize += bytesWritten;
        written += bytesWritten;
    }

    return totalSize;
}

