public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 2) {
        throw new IllegalArgumentException("desiredCapacity must be >= 2");
    }
    if (desiredCapacity < 1000) {
        return nextPrimeImpl(desiredCapacity);
    } else {
        while (true) {
            final int result = nextPrimeImpl(desiredCapacity);
            final int count = countPrimes(0, result);
            if (count > 0) {
                return result;
            }
        }
    }
}

public static int nextPrime(int desiredCapacity){
    if(desiredCapacity <= 1) return 2;

    int temp = desiredCapacity&~3;
    while (true) {
        int n = (temp + 2) | 3;
        if (isPrime(n)) return n;
        temp += 4;
    }
