                                unicodeCodePoint = (unicodeCodePoint * 16) + Character.digit(midFour, 16);
                                unicodeCodePoint = (unicodeCodePoint * 16) + Character.digit(lowFour, 16);
                                unicodeCodePoint = (unicodeCodePoint * 16) + Character.digit(digit1, 16);
                                unicodeCodePoint = (unicodeCodePoint * 16) + Character.digit(digit2, 16);
                                unicodeCodePoint = (unicodeCodePoint * 16) + Character.digit(digit3, 16);
                                unicodeCodePoint = (unicodeCodePoint * 16) + Character.digit(digit4, 16);
                                escapedStr = escapedStr.substring(0, i) + (char) unicodeCodePoint + escapedStr.substring(i + 8);
                                i += 8; // Skip the next 8 characters.
                            } else {
