                            }
                            break;
                        default:
                            // Invalid escape sequence, continue to next character.
                            break;
                    }
                } else {
                    throw new UnsupportedOperationException("Invalid escape sequence.");
                }
                break;
            case '\'':
                if (i < escapedStr.length() - 1) {
                    char nextChar = escapedStr.charAt(i + 1);
                    if (nextChar == '\'') {
