                }
                for (E neighbor : graph.getNeighbors(vertex)) {
                    if (!visited.contains(neighbor)) {
                        stack.push(neighbor);
                        visited.add(neighbor);
                    }
                }
            }
            if (!stack.isEmpty()) {
                throw new IllegalArgumentException("Graph contains cycles or inconsistent edges");
            }
        }
    }

    return path;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Check if the graph is not null and the set of edges is not null
    if (graph == null || tour == null) {
        throw new IllegalArgumentException("Both graph and tour cannot be null");
    }

    // Initialize the graph path
    GraphPath<V, E> tourPath = new GraphPath<>(graph);

    // Iterate through each edge in the set
    for (E edge : tour) {
        // Get the source and destination nodes of the edge
        V sourceNode = graph.vertexSet().iterator().next();
        V targetNode = graph.edge(edge).getTarget();

        // Add an edge to the graph path with the destination node as the succeeding vertex
        tourPath.addEdge(sourceNode, targetNode);
    }

    return tourPath;
}

