private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add(sum);
    }
    return new Pair<>(suffixSum, sum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    ArrayList<Integer> suffixSum = new ArrayList<>();
    if (bounds != null && !bounds.isEmpty()) {
        List<Integer> reversed = new ArrayList<>(bounds);
        Collections.reverse(reversed);
        long totalSum = 0;
        for (int i = 0; i < reversed.size(); i++) {
            suffixSum.add(totalSum * (reversed.size() - i));
            totalSum += reversed.get(i);
        }
        Collections.reverse(suffixSum);
    }
    return new Pair<>(suffixSum, totalSum);
}

