    public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        if (bounds == null || bounds.isEmpty()) {
            return new Pair<>(List.of(), 0L);
        }

        List<Integer> suffixSum = new ArrayList<>(bounds.size());
        long sum = 0;

        for (int i = bounds.size() - 1; i >= 0; i--) {
            sum += bounds.get(i);
            suffixSum.add(sum);
        }

        return new Pair<>(suffixSum, sum);
    }

}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>(); // Initialize the suffix sum list
    Long sum = 0L; // Initialize the sum variable

    for (int i = 0; i < bounds.size(); i++) {
        sum += bounds.get(i); // Add current element to sum
        suffixSum.add((int) sum); // Add computed suffix sum to list
    }

    // Sum of all elements in the given list
    long totalSum = bounds.stream().mapToInt(Integer::intValue).sum();

    return new Pair<>(suffixSum, totalSum); // Return the computed pair of suffix sum list and total sum
}

