        this.data = newData;
    }

    // Step 3: Write the int into the byte array
    this.data[this.data.length - 4] = (byte) (intValue & 0xFF);
    this.data[this.data.length - 3] = (byte) ((intValue >> 8) & 0xFF);
    this.data[this.data.length - 2] = (byte) ((intValue >> 16) & 0xFF);
    this.data[this.data.length - 1] = (byte) ((intValue >> 24) & 0xFF);

    // Step 4: Return the updated vector
    return this;
}

