private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.isEmpty()) {
        return false; // Early return for invalid inputs
    }

    int n = vertices.size();
    if (n < 3) {
        return true; // A subgraph with 0 or 1 vertex is always a clique
    }

    // Check all possible pairs of vertices in the Set
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2 && !graph.isAdjacent(v1, v2)) {
                return false; // Found an edge that isn't adjacent in graph
            }
        }
    }

    return true; // All vertices are adjacent in graph, thus forming a clique
}

private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices) {
    if (vertices.size() == 0 || vertices.size() == 1) {
        return true;
    }
    List<V> sortedVertices = new ArrayList<>(vertices);
    Collection<E> edges = graph.edges();
    for (E edge : edges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (!sortedVertices.contains(source) || !sortedVertices.contains(target)) {
            return false;
        }
        if (sortedVertices.indexOf(source) < sortedVertices.indexOf(target)) {
            sortedVertices.remove(source);
        }
    }
    return sortedVertices.isEmpty();
}

public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if there is only one vertex left
    if (vertices.size() == 1) {
        return true;
    }

    // Iterate through all combinations of vertices
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 == v2) continue;
            if (graph.containsEdge(v1, v2) || graph.containsEdge(v2, v1)) return false;
        }
    }

    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices cannot be null");
    }
    int n = vertices.size();
    if (n <= 1) {
        return true;
    }
    int maxDegree = Integer.MIN_VALUE;
    for (V vertex : vertices) {
        int degree = graph.degreeOf(vertex);
        if (degree > maxDegree) {
            maxDegree = degree;
        }
    }
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1.equals(vertex2)) continue;
            if (!graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }
    return true;
}

