public static String applyRelativePath(String path, String relativePath) {
  // Check if the path is null or empty
  if (path == null || path.isEmpty()) {
    return relativePath;
  }

  // Split the path and relative path into lists of strings
  String[] pathParts = path.split("/");
  String[] relativePathParts = relativePath.split("/");

  // Loop through the relative path parts and append them to the path parts
  int i = 0;
  for (String part : relativePathParts) {
    // If the part is an empty string, skip it
    if (part.isEmpty()) {
      continue;
    }

    // If the part starts with "parent", remove it
    if (part.startsWith("parent")) {
      pathParts.pop();
    } else {
      pathParts.add(part);
    }

    i++;
  }

  // Join the path parts back into a single string and prepend with the original path's prefix
  String result = String.join("/", pathParts);
  if (path.startsWith("/")) {
    result = "/" + result;
  }

  return result;
}

public static String applyRelativePath(String path, String relativePath) {
    int lastIndex = path.lastIndexOf("/");
    if (lastIndex == -1) {
        // If there's no slash, the path is already a full file path.
        return path + relativePath;
    } else {
        // Build the new path by combining the directory part and the relative path.
        return path.substring(0, lastIndex) + relativePath;
    }
}

